import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { componentAttrs } from "../_utils/component.helper";

const NTG_HOME_URL = "https://nt.gov.au";
const NTG_LOGO_URL = "https://nt.gov.au/_design/css/main.css/logo-ntg-mono.svg";
const COPYRIGHT_OWNER = "Northern Territory Government of Australia";
const DEFAULT_FINAL_TEXT =
  "The Northern Territory Government acknowledges the Traditional Owners of the Northern Territory and recognises their continuing cultural and spiritual connections to the lands, waters and communities. We pay our respects to all Aboriginal and Torres Strait Islander people and their cultures, their Elders past and present, and to future generations.";

const DETECTABLE_BRANDS = [
  {
    match: /facebook/i,
    iconClass: "fab fa-facebook-square",
    label: "Facebook",
  },
  {
    match: /linkedin/i,
    iconClass: "fab fa-linkedin",
    label: "LinkedIn",
  },
  {
    match: /youtube|youtu\.be/i,
    iconClass: "fab fa-youtube-square",
    label: "YouTube",
  },
  {
    match: /instagram/i,
    iconClass: "fab fa-instagram",
    label: "Instagram",
  },
  {
    match: /have\s*your\s*say|consult|engage|comment/i,
    iconClass: "fal fa-comment",
    label: "Have your say",
  },
  {
    match: /x\.com|twitter/i,
    iconClass: "fab fa-x-twitter",
    label: "X",
  },
];

export default {
  async main(input = {}) {
    const { menus = [], ancillary = [], finalText = "" } = input;

    return /* html */ `
    <footer ${componentAttrs("footer", input)} class="ntg-footer" role="contentinfo">
        <div class="footer__inner">
            ${renderTop(menus)}
            ${renderMiddle(ancillary)}
            ${renderBottom(finalText)}
        </div>
    </footer>`;
  },
};

function renderTop(menus) {
  const groups = (Array.isArray(menus) ? menus : [])
    .map((menu, index) => renderMenuGroup(menu, index))
    .filter(Boolean)
    .join("");

  if (!groups) return "";

  return `
    <div class="footer__top">
      <div class="footer__groups">
${groups}
      </div>
    </div>`;
}

function renderMiddle(ancillary) {
  const links = (Array.isArray(ancillary) ? ancillary : [])
    .map(renderAncillaryLink)
    .filter(Boolean)
    .join("");

  return `
    <div class="footer__middle">
      <div class="footer__brand">
        <a href="${escURL(NTG_HOME_URL)}">
          <img src="${escURL(NTG_LOGO_URL)}" alt="Visit NT.GOV.AU" />
        </a>
      </div>
      ${links ? `<nav class="footer__ancillary" aria-label="Footer links"><ul class="footer__ancillary-list">${links}</ul></nav>` : ""}
    </div>`;
}

function renderBottom(finalText) {
  const year = new Date().getFullYear();
  const text = String(finalText ?? "").trim() || DEFAULT_FINAL_TEXT;

  return `
    <div class="footer__bottom">
      <div>${escHTML(text)}</div>
      <div>&copy; ${year} ${escHTML(COPYRIGHT_OWNER)}</div>
    </div>`;
}

function renderMenuGroup(menu, index) {
  if (!menu || typeof menu !== "object") return "";

  const title = String(menu.menuTitle ?? "").trim();
  const menuType = ["bullet", "icon", "none"].includes(menu.menuType)
    ? menu.menuType
    : "bullet";
  const items = Array.isArray(menu.menuItems) ? menu.menuItems : [];
  const renderedItems = items.map((item) => renderMenuItem(item, menuType)).filter(Boolean).join("");

  if (!title && !renderedItems) return "";

  return `
        <section class="footer__group footer__group--${escHTML(menuType)}" aria-labelledby="footer-group-${index}">
          ${title ? `<h2 id="footer-group-${index}">${escHTML(title)}</h2>` : ""}
          ${renderedItems ? `<ul class="footer__menu footer__menu--${escHTML(menuType)}">${renderedItems}</ul>` : ""}
        </section>`;
}

function renderAncillaryLink(item) {
  const link = normalizeLink(item);
  if (!link) return "";
  return `<li>${renderLink(link, "none")}</li>`;
}

function renderMenuItem(item, menuType) {
  const link = normalizeLink(item);
  if (link) {
    return `<li>${renderLink(link, menuType)}</li>`;
  }

  const richText = normalizeFormattedText(item);
  if (!richText) return "";

  return `<li>${richText}</li>`;
}

function renderLink(link, menuType) {
  const iconClass = normalizeIconClass(link.icon, link);
  const showIcon = menuType === "icon";
  const title = link.title || link.url;
  const contentHtml = showIcon
    ? renderIcon(iconClass, title) || escHTML(title)
    : escHTML(title);
  const targetAttr = link.target ? ` target="${escHTML(link.target)}"` : "";
  const relAttr = link.rel ? ` rel="${escHTML(link.rel)}"` : "";

  return `<a href="${escURL(link.url)}"${targetAttr}${relAttr} class="plain"><span class="decorate">${contentHtml}</span></a>`;
}

function renderIcon(iconClass, label) {
  if (!iconClass) return "";
  return `<span class="footer__icon" aria-hidden="true"><i class="${escHTML(iconClass)}"></i></span><span>${escHTML(label)}</span>`;
}

function normalizeLink(item) {
  if (!item) return null;

  if (typeof item === "string") {
    return {
      url: item,
      title: item,
      target: "",
      rel: "",
      icon: "",
    };
  }

  const source = item.link && typeof item.link === "object" ? item.link : item;
  const url =
    source.url ||
    source.href ||
    source.asset_url ||
    source.assetUrl ||
    source.linkUrl ||
    "";
  const title =
    source.title ||
    source.name ||
    source.label ||
    source.text ||
    source.linkText ||
    source.asset_name ||
    source.assetName ||
    url;
  const target = source.target || (source.newWindow ? "_blank" : "");
  const rel = source.rel || (target === "_blank" ? "noopener noreferrer" : "");

  const link = {
    url,
    title,
    label: title,
    target,
    rel,
    icon: source.icon || "",
  };

  return url ? link : null;
}

function normalizeFormattedText(item) {
  if (typeof item === "string") return item;
  if (!item || typeof item !== "object") return "";

  return (
    item.html ||
    item.value ||
    item.body ||
    item.content ||
    item.text ||
    ""
  );
}

function normalizeIconClass(rawIcon, link) {
  const value = String(rawIcon ?? "").trim();

  if (!value || value === "DETECT_BRAND_ICON") {
    return detectBrand(link)?.iconClass || "";
  }

  if (/^fa[srlbd]?\s+fa-[a-z0-9-]+$/i.test(value)) return value;
  if (/^fa-[a-z0-9-]+$/i.test(value)) return `fal ${value}`;
  if (/^[a-z0-9-]+$/i.test(value)) return `fal fa-${value}`;

  return sanitizeIconClass(value);
}

function detectBrand(link) {
  const haystack = [link.url, link.title, link.label].filter(Boolean).join(" ");
  return DETECTABLE_BRANDS.find((brand) => brand.match.test(haystack)) || null;
}

function sanitizeIconClass(value) {
  const iconClass = String(value ?? "").trim();
  if (!iconClass) return "";
  if (!/^[a-z0-9\s_-]+$/i.test(iconClass)) return "";
  return iconClass;
}